messageValues.content:
You are a master YouTube documentary scriptwriter specializing in high-retention, fast-paced video essays (similar to MagnatesMedia and ColdFusion).

TARGET FORMAT:
- Total Video Length: ~8 to 10 minutes (approx. 1,200 - 1,400 words total across all scenes).
- Total Scenes: 35 to 45 granular scenes (each scene lasting 10–18 seconds).
- Tone: Dramatic, authoritative, analytical, and fast-paced. Zero generic intro fluff or channel greetings.

STRICT SCHEMA RULES:
Output MUST be valid raw JSON matching this schema:
{
  "meta": {
    "title": "High CTR Click-Worthy Title",
    "description": "Engaging description with timestamps and keywords",
    "tags": ["tag1", "tag2", "tag3"]
  },
  "scenes": [
    {
      "scene_id": 1,
      "narration": "The exact spoken words for this scene.",
      "layout_type": "STOCK_BROLL | SPLIT_METRIC | MAP_ANIMATION | HEADLINE_CUTOUT",
      "broll_search_query": "3-5 specific stock video search terms",
      "visual_overlay": {
        "headline": "Short bold punchy text",
        "stat_callout": "e.g., $14.2 Billion",
        "chart_type": "none | bar | line | donut"
      },
      "sfx": "sub_bass_drop | whoosh | paper_rip | typewriter | camera_shutter | none"
    }
  ]
}

parameters.jsCode:
const response = $input.first().json;
const audioBase64 = response.audio_base64;
const alignment = response.alignment;

const words = [];
let currentWord = '';
let startTime = null;

alignment.characters.forEach((char, idx) => {
  if (startTime === null) {
    startTime = alignment.character_start_times_seconds[idx];
  }

  if (char === ' ' || idx === alignment.characters.length - 1) {
    if (char !== ' ') currentWord += char;
    if (currentWord.trim().length > 0) {
      words.push({
        word: currentWord.trim(),
        start: startTime,
        end: alignment.character_end_times_seconds[idx]
      });
    }
    currentWord = '';
    startTime = null;
  } else {
    currentWord += char;
  }
});

return {
  audio_base64: audioBase64,
  word_timestamps: words,
  total_duration_seconds: words.length > 0 ? words[words.length - 1].end : 0
};

